(7360951, 1152355, 60862, '<td valign="top">Congrats on your surefire ribbon. :)</td>', 'Congrats on your surefire ribbon. :)', '2015-06-12 01:11:08.000000', NULL, 1),
(7360953, 1152748, 45631, '<td valign="top">Very clever.  Might just be my computer but the people don''t seem to be in focus. But still a good composition.</td>', 'Very clever.  Might just be my computer but the people don''t seem to be in focus. But still a good composition.', '2015-06-12 01:13:49.000000', NULL, 1),
(7360955, 1152207, 45631, '<td valign="top">Like this one.  Clever idea.</td>', 'Like this one.  Clever idea.', '2015-06-12 01:16:10.000000', NULL, 1),
(7360957, 1152355, 45631, '<td valign="top">Fabulous image.</td>', 'Fabulous image.', '2015-06-12 01:17:33.000000', NULL, 1),
(7361033, 1152207, 58667, '<td valign="top">Nice! The pencil on the left could be straight and more centered, but great idea.</td>', 'Nice! The pencil on the left could be straight and more centered, but great idea.', '2015-06-12 03:52:20.000000', NULL, 1),
(7361035, 1152220, 58667, '<td valign="top">The strong threshold B&amp;W is not my thing, but I can appreciate it here - I just have to look a bit longer... :)</td>', 'The strong threshold B&W is not my thing, but I can appreciate it here - I just have to look a bit longer... :)', '2015-06-12 03:55:06.000000', NULL, 1),
(7361037, 1152890, 58667, '<td valign="top">This is an interesting event, but to be honest, the colours don''t quite do it for me. Well composed nonetheless.</td>', 'This is an interesting event, but to be honest, the colours don''t quite do it for me. Well composed nonetheless.', '2015-06-12 03:57:00.000000', NULL, 1),
(7361038, 1152483, 58667, '<td valign="top">To me, this type of thing is boring, but I think about it as stock photography or something like that where the photo has a purpose. Great idea and well executed.</td>', 'To me, this type of thing is boring, but I think about it as stock photography or something like that where the photo has a purpose. Great idea and well executed.', '2015-06-12 03:58:17.000000', NULL, 1),
(7361039, 1152240, 58667, '<td valign="top">The guy''s expression is priceless.</td>', 'The guy''s expression is priceless.', '2015-06-12 03:59:00.000000', NULL, 1),
(7361041, 1152109, 58667, '<td valign="top">This is quite beautiful!</td>', 'This is quite beautiful!', '2015-06-12 03:59:42.000000', NULL, 1),
(7361042, 1152555, 58667, '<td valign="top">Clever! I''m wondering if a bit more contrast would have brought out the origami a bit better?</td>', 'Clever! I''m wondering if a bit more contrast would have brought out the origami a bit better?', '2015-06-12 04:00:47.000000', NULL, 1),
(7361047, 1152748, 58667, '<td valign="top">I love it, I just wish the people were a bit more in focus with a shallower DOF. I like the idea, the composition, the opposing lines - there''s a lot to love about this.</td>', 'I love it, I just wish the people were a bit more in focus with a shallower DOF. I like the idea, the composition, the opposing lines - there''s a lot to love about this.', '2015-06-12 04:06:13.000000', NULL, 1),
(7361048, 1152917, 58667, '<td valign="top">Build up, break down? I wish there was a little more DOF or context. It''s also not very easy to tell what this is with the monotone.</td>', 'Build up, break down? I wish there was a little more DOF or context. It''s also not very easy to tell what this is with the monotone.', '2015-06-12 04:08:34.000000', NULL, 1),
(7361049, 1152355, 58667, '<td valign="top">Well done. I like the opposing light sources too! Ooh, this would have been even better with a full reflection, I think. :)</td>', 'Well done. I like the opposing light sources too! Ooh, this would have been even better with a full reflection, I think. :)', '2015-06-12 04:10:13.000000', NULL, 1),
(7361089, 1152183, 58667, '<td valign="top">Interesting salt crystals. I find the two on top to be a little distracting... But this is different, which is good. :)</td>', 'Interesting salt crystals. I find the two on top to be a little distracting... But this is different, which is good. :)', '2015-06-12 05:39:50.000000', NULL, 1),
(7361091, 1152086, 58667, '<td valign="top">Haha! Well thought of! And very well executed. Photographically speaking, I find there are a few hot spots like on the slice of orange on the left, also the hue of the oranges seems a little off.</td>', 'Haha! Well thought of! And very well executed. Photographically speaking, I find there are a few hot spots like on the slice of orange on the left, also the hue of the oranges seems a little off.', '2015-06-12 05:41:20.000000', NULL, 1),
